const email = $('Prepare Email').first().json;
const geminiText = $json.content?.parts?.[0]?.text;

if (!geminiText) {
  throw new Error('Gemini response is empty');
}

const cleanedText = geminiText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let transaction;

try {
  transaction = JSON.parse(cleanedText);
} catch (error) {
  throw new Error(`Invalid Gemini JSON: ${error.message}`);
}

return {
  json: {
    ...email,
    ...transaction,
  },
};

// ============================================================
// Normalize Transaction
// Purpose:
// Convert Gemini transaction output into a consistent format
// before duplicate detection.
// ============================================================

const data = $json;

// ------------------------------------------------------------
// Helper functions
// ------------------------------------------------------------

function normalizeString(value) {
  if (value === null || value === undefined) {
    return null;
  }

  const result = String(value)
    .trim()
    .replace(/\s+/g, ' ');

  return result || null;
}

function normalizeMerchant(value) {
  const merchant = normalizeString(value);

  if (!merchant) {
    return null;
  }

  return merchant
    .toLowerCase()
    // Replace common punctuation with spaces
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    // Normalize whitespace
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeCurrency(value) {
  const currency = normalizeString(value);

  if (!currency) {
    return null;
  }

  return currency.toUpperCase();
}

function normalizeAmount(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  // If Gemini already returned a number
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      return null;
    }

    return Number(value.toFixed(2));
  }

  // Handle strings such as:
  // "$49.99"
  // "USD 49.99"
  // "49.99 USD"
  // "1,249.50"
  const cleaned = String(value)
    .trim()
    .replace(/,/g, '')
    .replace(/[^\d.-]/g, '');

  if (!cleaned) {
    return null;
  }

  const amount = Number(cleaned);

  if (!Number.isFinite(amount)) {
    return null;
  }

  return Number(amount.toFixed(2));
}

function normalizeDate(value) {
  if (!value) {
    return null;
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date.toISOString().split('T')[0];
}

function normalizeTimestamp(value) {
  if (!value) {
    return null;
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date.toISOString();
}

// ------------------------------------------------------------
// Extract and normalize fields
// ------------------------------------------------------------

const message_id = normalizeString(data.message_id);
const thread_id = normalizeString(data.thread_id);
const subject = normalizeString(data.subject);
const sender = normalizeString(data.sender);
const email_received_at = normalizeString(data.email_received_at);

const merchant = normalizeString(data.merchant);
const merchantNormalized = normalizeMerchant(data.merchant);

const amount = normalizeAmount(data.amount);

const currency = normalizeCurrency(data.currency);

const transactionDate = normalizeDate(data.transaction_date);

const transactionTimestamp = normalizeTimestamp(
  data.transaction_timestamp
);

const paymentReference = normalizeString(
  data.payment_reference
);

const transactionType =
  normalizeString(data.transaction_type)?.toUpperCase() || 'UNKNOWN';

const timestampSource =
  normalizeString(data.timestamp_source)?.toLowerCase() || null;

const timezone = normalizeString(data.timezone);

const amountSource =
  normalizeString(data.amount_source)?.toLowerCase() || null;

const extractionReason =
  normalizeString(data.extraction_reason);

const isPaymentConfirmation =
  data.is_payment_confirmation === true;

const extractionConfidence =
  typeof data.extraction_confidence === 'number'
    ? Math.min(Math.max(data.extraction_confidence, 0), 1)
    : 0;

const classificationConfidence =
  typeof data.classification_confidence === 'number'
    ? Math.min(Math.max(data.classification_confidence, 0), 1)
    : 0;

// ------------------------------------------------------------
// Validate transaction type
// ------------------------------------------------------------

const allowedTransactionTypes = [
  'CHARGE',
  'REFUND',
  'REVERSAL',
  'AUTHORIZATION',
  'FAILED_PAYMENT',
  'UNKNOWN',
];

const normalizedTransactionType =
  allowedTransactionTypes.includes(transactionType)
    ? transactionType
    : 'UNKNOWN';

// ------------------------------------------------------------
// Determine whether this transaction is eligible for
// duplicate-charge detection.
// ------------------------------------------------------------

const isValidCharge =
  isPaymentConfirmation === true &&
  normalizedTransactionType === 'CHARGE' &&
  merchant !== null &&
  merchantNormalized !== null &&
  amount !== null &&
  amount >= 0 &&
  currency !== null;

// ------------------------------------------------------------
// Create normalized transaction object
// ------------------------------------------------------------

return {
  json: {
    // Original extracted values
    message_id,
    thread_id,
    subject,
    sender,
    email_received_at,

    merchant,
    merchantNormalized,
    amount,
    currency,

    transaction_date: transactionDate,
    transaction_timestamp: transactionTimestamp,

    timestamp_source: timestampSource,
    timezone,

    payment_reference: paymentReference,

    transaction_type: normalizedTransactionType,

    amount_source: amountSource,

    extraction_confidence: extractionConfidence,
    classification_confidence: classificationConfidence,

    is_payment_confirmation: isPaymentConfirmation,

    extraction_reason: extractionReason,

    // Normalized values used by duplicate detection
    merchant_normalized: merchantNormalized,

    // Validation flag
    is_valid_charge: isValidCharge,

    // Placeholder fields for later nodes
    duplicate_status: 'NOT_CHECKED',
    duplicate_of: null,
    duplicate_confidence: null,
    duplicate_reason: null,
    time_difference_minutes: null,
  },
};

// ============================================================
// Generate Deterministic Transaction ID
// No external Node.js modules required
// ============================================================

const data = $json;

// ------------------------------------------------------------
// Helper
// ------------------------------------------------------------

function normalize(value) {
  if (value === null || value === undefined) {
    return '';
  }

  return String(value)
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

// ------------------------------------------------------------
// Email identity
// ------------------------------------------------------------

const emailMessageId =
  data.email_message_id ||
  data.message_id ||
  null;

if (!emailMessageId) {
  throw new Error(
    'Cannot generate transaction ID: email_message_id/message_id is missing.'
  );
}

// ------------------------------------------------------------
// Transaction fields
// ------------------------------------------------------------

const merchant = normalize(
  data.merchant_normalized || data.merchant
);

const amount =
  data.amount !== null &&
  data.amount !== undefined &&
  data.amount !== ''
    ? Number(data.amount).toFixed(2)
    : '';

const currency = normalize(data.currency);

const transactionTimestamp =
  normalize(data.transaction_timestamp);

const paymentReference =
  normalize(data.payment_reference);

// ------------------------------------------------------------
// Build deterministic source
// ------------------------------------------------------------

const transactionSource = [
  emailMessageId,
  merchant,
  amount,
  currency,
  transactionTimestamp,
  paymentReference
].join('|');

// ------------------------------------------------------------
// Simple deterministic hash
// ------------------------------------------------------------
// This does NOT require crypto or any external module.

function simpleHash(value) {
  let hash1 = 0x811c9dc5;
  let hash2 = 0x01000193;

  for (let i = 0; i < value.length; i++) {
    const char = value.charCodeAt(i);

    hash1 ^= char;
    hash1 = Math.imul(hash1, 16777619);

    hash2 ^= char + i;
    hash2 = Math.imul(hash2, 2246822519);
  }

  return (
    (hash1 >>> 0).toString(16).padStart(8, '0') +
    (hash2 >>> 0).toString(16).padStart(8, '0')
  );
}

const transactionHash = simpleHash(transactionSource);

// ------------------------------------------------------------
// Transaction ID
// ------------------------------------------------------------

const transactionId = `TXN-${transactionHash}`;

// ------------------------------------------------------------
// Return original data + generated ID
// ------------------------------------------------------------

return {
  json: {
    ...data,

    transaction_id: transactionId,

    transaction_id_source:
      'email_message_id_and_transaction_fields'
  }
};

// ============================================================
// Detect Duplicate Transaction
// ============================================================
//
// Purpose:
// Compare the current transaction against existing transactions
// from Google Sheets and determine whether it is a potential
// duplicate charge.
//
// Duplicate criteria:
// 1. Current transaction must be a valid CHARGE
// 2. Existing transaction must be a CHARGE
// 3. Different transaction/email
// 4. Same currency
// 5. Same amount
// 6. Same/similar merchant
// 7. Transaction time within 48 hours
//
// ============================================================

const current = $('Generate Transaction ID').first().json;

// ------------------------------------------------------------
// Configuration
// ------------------------------------------------------------

const DUPLICATE_WINDOW_HOURS = 48;
const DUPLICATE_WINDOW_MINUTES = DUPLICATE_WINDOW_HOURS * 60;

// ------------------------------------------------------------
// Helper functions
// ------------------------------------------------------------

function normalizeString(value) {
  if (value === null || value === undefined) {
    return '';
  }

  return String(value)
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function normalizeMerchant(value) {
  return normalizeString(value)
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeAmount(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const amount = Number(
    String(value)
      .replace(/,/g, '')
      .replace(/[^\d.-]/g, '')
  );

  if (!Number.isFinite(amount)) {
    return null;
  }

  return Number(amount.toFixed(2));
}

function parseTimestamp(value) {
  if (!value) {
    return null;
  }

  const timestamp = new Date(value).getTime();

  if (!Number.isFinite(timestamp)) {
    return null;
  }

  return timestamp;
}

// ------------------------------------------------------------
// Current transaction validation
// ------------------------------------------------------------

const currentMerchant = normalizeMerchant(
  current.merchant_normalized || current.merchant
);

const currentAmount = normalizeAmount(current.amount);

const currentCurrency = normalizeString(
  current.currency
).toUpperCase();

const currentTimestamp = parseTimestamp(
  current.transaction_timestamp
);

const currentTransactionType = normalizeString(
  current.transaction_type
).toUpperCase();

const currentTransactionId =
  current.transaction_id || null;

const currentEmailMessageId =
  current.email_message_id ||
  current.message_id ||
  null;

// ------------------------------------------------------------
// Default result
// ------------------------------------------------------------

let duplicateStatus = 'NORMAL';
let duplicateOf = null;
let duplicateConfidence = null;
let duplicateReason = null;
let timeDifferenceMinutes = null;

// ------------------------------------------------------------
// Only successful CHARGE transactions should be checked
// ------------------------------------------------------------

if (
  current.is_valid_charge !== true ||
  currentTransactionType !== 'CHARGE'
) {
  return {
    json: {
      ...current,

      duplicate_status: 'NOT_APPLICABLE',
      duplicate_of: null,
      duplicate_confidence: null,
      duplicate_reason:
        'Transaction is not a valid successful charge.',
      time_difference_minutes: null,
    },
  };
}

// ------------------------------------------------------------
// Get Google Sheets transactions
//
// This node is expected to be the node immediately before
// this Code node and return the existing transaction records.
//
// ------------------------------------------------------------

const existingTransactions =
  $input.all();

// ------------------------------------------------------------
// Find possible duplicate
// ------------------------------------------------------------

const possibleDuplicates = [];

for (const item of existingTransactions) {

  const existing = item.json;

  // ----------------------------------------------------------
  // Ignore the exact same transaction ID
  // ----------------------------------------------------------

  if (
    currentTransactionId &&
    existing.transaction_id &&
    currentTransactionId === existing.transaction_id
  ) {
    continue;
  }

  // ----------------------------------------------------------
  // Ignore the exact same Gmail message
  // ----------------------------------------------------------

  const existingEmailMessageId =
    existing.email_message_id ||
    existing.message_id ||
    null;

  if (
    currentEmailMessageId &&
    existingEmailMessageId &&
    currentEmailMessageId === existingEmailMessageId
  ) {
    continue;
  }

  // ----------------------------------------------------------
  // Existing transaction must be a successful charge
  // ----------------------------------------------------------

  const existingTransactionType =
    normalizeString(
      existing.transaction_type
    ).toUpperCase();

  if (existingTransactionType !== 'CHARGE') {
    continue;
  }

  // ----------------------------------------------------------
  // Merchant comparison
  // ----------------------------------------------------------

  const existingMerchant =
    normalizeMerchant(
      existing.merchant_normalized ||
      existing.merchant
    );

  if (!currentMerchant || !existingMerchant) {
    continue;
  }

  // Exact normalized merchant comparison for now
  //
  // We can add more advanced fuzzy matching later if required.
  //

  if (currentMerchant !== existingMerchant) {
    continue;
  }

  // ----------------------------------------------------------
  // Amount comparison
  // ----------------------------------------------------------

  const existingAmount =
    normalizeAmount(existing.amount);

  if (
    currentAmount === null ||
    existingAmount === null
  ) {
    continue;
  }

  if (currentAmount !== existingAmount) {
    continue;
  }

  // ----------------------------------------------------------
  // Currency comparison
  // ----------------------------------------------------------

  const existingCurrency =
    normalizeString(
      existing.currency
    ).toUpperCase();

  if (
    !currentCurrency ||
    !existingCurrency ||
    currentCurrency !== existingCurrency
  ) {
    continue;
  }

  // ----------------------------------------------------------
  // Timestamp comparison
  // ----------------------------------------------------------

  const existingTimestamp =
    parseTimestamp(
      existing.transaction_timestamp
    );

  if (
    currentTimestamp === null ||
    existingTimestamp === null
  ) {
    continue;
  }

  // Difference in minutes
  const differenceMinutes =
    Math.abs(
      currentTimestamp -
      existingTimestamp
    ) / (1000 * 60);

  // ----------------------------------------------------------
  // Must be within 48 hours
  // ----------------------------------------------------------

  if (
    differenceMinutes >
    DUPLICATE_WINDOW_MINUTES
  ) {
    continue;
  }

  // ----------------------------------------------------------
  // Calculate confidence
  // ----------------------------------------------------------

  let confidence;

  if (differenceMinutes <= 360) {
    // 0–6 hours
    confidence = 'HIGH';
  } else if (differenceMinutes <= 1440) {
    // 6–24 hours
    confidence = 'MEDIUM_HIGH';
  } else {
    // 24–48 hours
    confidence = 'MEDIUM';
  }

  possibleDuplicates.push({
    transaction: existing,
    differenceMinutes,
    confidence,
  });
}

// ------------------------------------------------------------
// Select closest matching transaction
// ------------------------------------------------------------

if (possibleDuplicates.length > 0) {

  possibleDuplicates.sort(
    (a, b) =>
      a.differenceMinutes -
      b.differenceMinutes
  );

  const bestMatch =
    possibleDuplicates[0];

  duplicateStatus = 'POTENTIAL_DUPLICATE';

  duplicateOf =
    bestMatch.transaction.transaction_id ||
    null;

  duplicateConfidence =
    bestMatch.confidence;

  timeDifferenceMinutes =
    Number(
      bestMatch.differenceMinutes.toFixed(2)
    );

  duplicateReason =
    `Same merchant, amount, and currency found within ` +
    `${timeDifferenceMinutes} minutes of an existing charge.`;
}

// ------------------------------------------------------------
// Return current transaction + duplicate result
// ------------------------------------------------------------

return {
  json: {
    ...current,

    duplicate_status: duplicateStatus,

    duplicate_of: duplicateOf,

    duplicate_confidence:
      duplicateConfidence,

    duplicate_reason:
      duplicateReason,

    time_difference_minutes:
      timeDifferenceMinutes,
  },
};

// ============================================================
// Extract Gmail Email Body
// ============================================================

const message = $json;

function decodeBase64Url(data) {
  if (!data) {
    return '';
  }

  // Gmail uses base64url:
  // - instead of +
  // - instead of /
  // and may omit padding =
  const base64 = data
    .replace(/-/g, '+')
    .replace(/_/g, '/');

  const padded =
    base64 + '='.repeat((4 - (base64.length % 4)) % 4);

  return Buffer.from(padded, 'base64').toString('utf8');
}

function extractParts(part) {
  if (!part) {
    return {
      plainText: '',
      html: '',
    };
  }

  let plainText = '';
  let html = '';

  // Direct body
  if (part.body?.data) {
    const decoded = decodeBase64Url(part.body.data);

    if (part.mimeType === 'text/plain') {
      plainText += decoded;
    }

    if (part.mimeType === 'text/html') {
      html += decoded;
    }
  }

  // Nested MIME parts
  if (Array.isArray(part.parts)) {
    for (const child of part.parts) {
      const result = extractParts(child);

      plainText += result.plainText;
      html += result.html;
    }
  }

  return {
    plainText,
    html,
  };
}

const result = extractParts(message.payload);

// Prefer plain text because Gemini doesn't need HTML markup.
let emailBody = result.plainText || result.html || '';

if (!emailBody.trim()) {
  // Fallback to Gmail snippet
  emailBody = message.snippet || '';
}

return {
  json: {
    message_id: message.id,
    thread_id: message.threadId,

    subject:
      message.payload?.headers?.find(
        h => h.name.toLowerCase() === 'subject'
      )?.value || '',

    sender:
      message.payload?.headers?.find(
        h => h.name.toLowerCase() === 'from'
      )?.value || '',

    email_body: emailBody,

    email_received_at: message.internalDate || null,

    body_source: result.plainText
      ? 'text/plain'
      : result.html
        ? 'text/html'
        : 'snippet',
  },
};
